export function evaluate(source) {
  if (typeof source !== "string") {
    throw new TypeError("Expression must be a string");
  }

  let position = 0;

  function skipWhitespace() {
    while (/\s/.test(source[position] ?? "")) position++;
  }

  function fail() {
    throw new SyntaxError(`Invalid expression at position ${position}`);
  }

  function checked(value) {
    if (!Number.isFinite(value)) {
      throw new RangeError("Expression result must be finite");
    }
    return value;
  }

  function parsePrimary() {
    skipWhitespace();

    if (source[position] === "(") {
      position++;
      const value = parseExpression();
      skipWhitespace();
      if (source[position] !== ")") fail();
      position++;
      return value;
    }

    const match = /^(?:\d+(?:\.\d+)?|\.\d+)/.exec(source.slice(position));
    if (!match) fail();
    position += match[0].length;
    return checked(Number(match[0]));
  }

  function parsePower() {
    const base = parsePrimary();
    skipWhitespace();

    if (source.slice(position, position + 2) === "**") {
      position += 2;
      return checked(base ** parseUnary());
    }

    return base;
  }

  function parseUnary() {
    skipWhitespace();

    if (source[position] === "+") {
      position++;
      return parseUnary();
    }
    if (source[position] === "-") {
      position++;
      return checked(-parseUnary());
    }

    return parsePower();
  }

  function parseMultiplication() {
    let value = parseUnary();

    while (true) {
      skipWhitespace();
      const operator = source[position];
      if (operator !== "*" && operator !== "/") break;
      position++;
      const right = parseUnary();
      value = checked(operator === "*" ? value * right : value / right);
    }

    return value;
  }

  function parseExpression() {
    let value = parseMultiplication();

    while (true) {
      skipWhitespace();
      const operator = source[position];
      if (operator !== "+" && operator !== "-") break;
      position++;
      const right = parseMultiplication();
      value = checked(operator === "+" ? value + right : value - right);
    }

    return value;
  }

  const value = parseExpression();
  skipWhitespace();
  if (position !== source.length) fail();
  return checked(value);
}
